        assert_eq!(state(cx), (ChainState::Running, TaskStatus::Running, 0));
        prompt_mode.update(cx, |this, _| this.tasks[1].status = TaskStatus::Failed);
        assert_eq!(state(cx), (ChainState::Over, TaskStatus::Failed, 2));
    }

